annualized_return_LFL &lt;- function(
    x,
    periods = 12
) {
  prod(1 + x)^(periods / length(x)) - 1
}

annualized_volatility_LFL &lt;- function(
    x,
    periods = 12
) {
  sd(x) * sqrt(periods)
}

maximum_drawdown_LFL &lt;- function(x) {
  wealth &lt;- cumprod(1 + x)
  drawdown &lt;- wealth / cummax(wealth) - 1
  min(drawdown)
}


